mapper.select:
select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, ETR_ENTRUST_ADD.EXC_DEAL_TYPE excDealType, ETR_ENTRUST_ADD.CUR_PAIR curPair, ETR_ENTRUST.PS ps, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST_ADD.TERM_TYPE termType, ETR_ENTRUST_ADD.VDATE settleVdate, ETR_ENTRUST_ADD.MDATE settleMdate, ETR_ENTRUST.PRICE price, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_ENTRUST_ADD.COR_CCY corCcy, ETR_ENTRUST_ADD.EXP_COR_AMT expCorAmt, nvl(ETR_FINISH_STATUS_A.FINISH_AMT, 0) finishAmt, decode(ETR_ENTRUST.ENTRUST_AMT,0,0,round(nvl(ETR_FINISH_STATUS_A.FINISH_AMT, 0) / ETR_ENTRUST.ENTRUST_AMT, 2) * 100) transactioncom, ETR_ENTRUST.REMARK remark from ETR_ENTRUST left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID
inner join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(nvl(FINISH_AMT,0)) as FINISH_AMT from ETR_FINISH_STATUS group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND (PTL_PORTFOLIO.PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
or PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN (
#{prot}
)
AND ETR_ENTRUST_ADD.EXC_DEAL_TYPE = #{excDealType,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.CUR_PAIR = #{curPair,jdbcType=VARCHAR}
AND ETR_ENTRUST.PS IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus,jdbcType=VARCHAR}
AND ETR_ENTRUST.VDATE >= #{startDate,jdbcType=DATE}
AND ETR_ENTRUST.MDATE <= #{endDate,jdbcType=DATE}
AND ETR_ENTRUST.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND NOT EXISTS (SELECT 1 FROM FIN_PRODUCT WHERE FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID)

select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_NAME finprodName, ETR_ENTRUST_ADD.EXC_DEAL_TYPE excDealType, ETR_ENTRUST_ADD.CUR_PAIR curPair, ETR_ENTRUST.PS ps, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST_ADD.TERM_TYPE termType, ETR_ENTRUST_ADD.VDATE settleVdate, ETR_ENTRUST_ADD.MDATE settleMdate, ETR_ENTRUST.PRICE price, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_ENTRUST.PRO_AVAILABLE_CASH proAvailableCash, ETR_ENTRUST_ADD.COR_CCY corCcy, ETR_ENTRUST_ADD.EXP_COR_AMT expCorAmt, ETR_ENTRUST_ADD.COR_CUR_POS corCurPos, ETR_ENTRUST_ADD.IS_DIF_SQU isDifSqu, ETR_ENTRUST.INV_AIM invAim, ETR_ENTRUST_ADD.DEAL_CUR_ACCT dealCurAcct, ETR_ENTRUST_ADD.COR_CUR_ACCT corCurAcct, ETR_ENTRUST_ADD.CNY_ACCT cnyAcct, ETR_ENTRUST.INV_MANAGER_ID invManagerId, ETR_DISTRIBUTE.TRADER trader, ETR_ENTRUST.COUNTER_ID counterId, ETR_ENTRUST.COUNTER_TRADER counterTrader, ETR_ENTRUST.CONTACT_INFO contactInfo, ETR_ENTRUST.REMARK remark from ETR_ENTRUST left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID
left join FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID
inner join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join ETR_DISTRIBUTE on ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID where ETR_ENTRUST.ENTRUST_ID = #{entrustId,jdbcType=VARCHAR}
